// ECOSTRESS spectrum files: a header of "Key: value" lines, then wavelength and value pairs.
export function parseSpectrum(text) {
  const lines = text.split(/\r?\n/);
  const header = {};
  let i = 0;
  for (; i < lines.length && /^[A-Za-z ]+:/.test(lines[i]); i += 1) {
    const [key, ...rest] = lines[i].split(':');
    header[key.trim().toLowerCase()] = rest.join(':').trim();
  }
  const scale = /percent/i.test(header['y units'] ?? '') ? 0.01 : 1;
  const pairs = lines.slice(i).filter((line) => line.trim()).map((line) => line.trim().split(/\s+/).map(Number));
  pairs.sort((a, b) => a[0] - b[0]);
  return {
    name: header.name,
    wavelengths: pairs.map((p) => p[0]),
    reflectance: pairs.map((p) => p[1] * scale),
  };
}
